#!/usr/bin/env python3
"""Extract source-bound mechanics notes. No game execution or third-party modules.

Run from any directory: python wiki/scripts/extract_mechanics.py
--check compares generated bytes without writing. Source hashes cover original bytes,
including CRLF. Line ranges are one-based, inclusive. Evidence IDs are local to this
extractor, not REA native-analysis evidence IDs.
"""
from __future__ import annotations

import argparse
import hashlib
import html
import json
from pathlib import Path
import re
import sys
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[2]
OUTPUT = ROOT / 'wiki/data/mechanics.json'
SDK = 'sdk/data/game_constants.xml'
DEBUG = 'rom/data/realtime_values/general_debug.txt'
ENV = 'rom/data/realtime_values/environment.txt'
TRADE = 'rom/data/missions/default_resource_trading/script.lua'
STORAGE = 'rom/data/missions/default_resource_storage/script.lua'
OIL = 'rom/data/missions/default_oil_survey/script.lua'
CARGO = 'rom/data/missions/default_cargo/script.lua'
CACHE: dict[str, tuple[str, str]] = {}
CONSTANTS: list[dict] = []
ARTICLES: list[dict] = []


def read(path):
    if path not in CACHE:
        data = (ROOT / path).read_bytes()
        CACHE[path] = (data.decode('utf-8-sig'), hashlib.sha256(data).hexdigest())
    return CACHE[path][0]


def source(path, start, end):
    read(path)
    assert 1 <= start <= end <= len(read(path).splitlines())
    return dict(path=path, sha256=CACHE[path][1], lineStart=start, lineEnd=end)


def span(path, match):
    text = read(path)
    return source(path, text.count('\n', 0, match.start()) + 1,
                  text.count('\n', 0, match.end() - 1) + 1)


def evidence_id(src):
    return f"resource:{src['path']}:{src['sha256'][:12]}:L{src['lineStart']}-L{src['lineEnd']}"


def value(raw):
    try:
        return int(raw)
    except ValueError:
        try:
            return float(raw.removesuffix('f'))
        except ValueError:
            return raw


def attrs(tag):
    # Shipped definitions contain attributes named 00, 01, etc. These are not
    # XML-compliant names. Scan only selected opening tags; never repair input.
    return {k: html.unescape(v) for k, v in re.findall(r'([\w]+)="([^"]*)"', tag)}


def constant(name, raw, description, src, kind, **extra):
    item = dict(name=name, value=value(raw), rawValue=raw, description=description,
                source=src, evidenceId=evidence_id(src), status='observed',
                evidenceType=kind, **extra)
    CONSTANTS.append(item)
    return item


def finding(label, val, detail, src, status='observed', kind=None):
    if kind is None:
        path = src['path']
        if '/missions/' in path:
            kind = 'static-addon-lua'
        elif '/definitions/' in path:
            kind = 'component-interface-description'
        elif '/realtime_values/' in path:
            kind = 'realtime-configuration'
        else:
            kind = 'sdk-configuration'
    return dict(label=label, value=val, detail=detail, evidenceId=evidence_id(src),
                source=src, status=status, evidenceType=kind)


def cite(path, needle, end=None):
    text = read(path)
    start = text.index(needle)
    stop = start + len(needle) if end is None else text.index(end, start) + len(end)
    return source(path, text.count('\n', 0, start) + 1, text.count('\n', 0, stop - 1) + 1)


def article(id, title, category, summary, body, findings, limitations):
    ARTICLES.append(dict(id=id, title=title, category=category, summary=summary,
                         body=body, findings=findings, limitations=limitations))


def extract_constants():
    text = read(SDK)
    # Strict parsing is safe for this SDK document, unlike block definitions.
    root = ET.fromstring(text)
    docs = {}
    group = ''
    for number, line in enumerate(text.splitlines(), 1):
        if '<!--' in line:
            group = line.split('<!--', 1)[1].strip()
        m = re.match(r'\s*(\w+)\s*-\s*(.*?)\s*- Default:\s*(\S+)\s*$', line)
        if m:
            name, description, raw = m.groups()
            docs[name] = (description, group)
            constant(name, raw, description, source(SDK, number, number), 'sdk-documented-default', category=group)
    for name, raw in root.attrib.items():
        m = re.search(r'\b' + re.escape(name) + r'\s*=\s*"' + re.escape(raw) + '"', text)
        description, group = docs.get(name, ('No description supplied.', ''))
        constant(name, raw, description, span(SDK, m), 'sdk-configuration', category=group)
    for path in sorted((ROOT / 'rom/data/realtime_values').glob('*.txt')):
        rel = path.relative_to(ROOT).as_posix()
        for number, line in enumerate(read(rel).splitlines(), 1):
            m = re.fullmatch(r'\s*(s32|f32|vec2|vec3|vec4|color8)\s+(\w+)\s+(.+?)\s*', line)
            if not m:
                if line.strip() and not line.lstrip().startswith(('#', '//')):
                    raise ValueError(f'Unparsed realtime record {rel}:{number}: {line!r}')
                continue
            typ, name, raw = m.groups()
            item = constant(name, raw, 'Named value in the shipped realtime configuration; runtime loading and units require separate confirmation.', source(rel, number, number), 'realtime-configuration', declaredType=typ)
            if typ.startswith('vec') or typ == 'color8':
                item['value'] = [value(s.strip()) for s in raw.split(',')]


def config(name, kind='realtime-configuration', path=None):
    items = [c for c in CONSTANTS if c['name'] == name and c['evidenceType'] == kind and (path is None or c['source']['path'] == path)]
    if len(items) != 1:
        raise ValueError(f'Expected one {name} / {kind}: {len(items)}')
    c = items[0]
    return finding(name, c['value'], c['description'], c['source'], kind=c['evidenceType'])


def definition(name, fields=(), nodes=True, tooltip=False, labels=False, short_tooltip=False):
    path = f'rom/data/definitions/{name}.xml'
    text = read(path)
    root = re.search(r'<definition\b[^>]*>', text)
    a = attrs(root[0])
    result = []
    for field in fields:
        m = re.search(r'\b' + re.escape(field) + r'="[^"]*"', text[root.start():root.end()])
        src = source(path, text.count('\n', 0, root.start() + m.start()) + 1,
                     text.count('\n', 0, root.start() + m.end() - 1) + 1)
        c = constant(f'{name}.{field}', a[field], f"{a['name']} definition field {field}; internal units unless explicitly documented.", src, 'component-configuration', component=name)
        result.append(finding(f"{a['name']}: {field}", c['value'], c['description'], src, kind='component-configuration'))
    if nodes:
        for m in re.finditer(r'<logic_node\b[^>]*>', text):
            node = attrs(m[0])
            if node.get('description'):
                result.append(finding(f"{a['name']}: {node.get('label', '')}", node['description'], 'Shipped connection description. This documents the interface; it is not a runtime measurement.', span(path, m)))
            elif labels and node.get('label'):
                result.append(finding(f"{a['name']}: {node['label']}", node['label'], 'Shipped port label only. No description, units, range or numeric node-type interpretation is supplied here.', span(path, m)))
    if tooltip:
        m = re.search(r'<tooltip_properties\b[^>]*>', text)
        node = attrs(m[0])
        result.append(finding(a['name'], node.get('description') or node.get('short_description'), 'Shipped component tooltip.', span(path, m)))
        if short_tooltip and node.get('short_description'):
            result.append(finding(f"{a['name']}: short tooltip", node['short_description'], 'Shipped short component tooltip.', span(path, m)))
    return result


def lua(label, val, detail, path, needle, end=None, status='observed'):
    return finding(label, val, detail, cite(path, needle, end), status)


